int my_find_prime_sup(int nb)
{
    int i = 1;
    int continuer = 0;
    int prime = 0;
    int a = 0;

    while (prime == 0) {
        nb = nb + a;
        for (i = 1; i <= nb; i++) {
            if ((nb % i) == 0)
                continuer++;
        }
        if (continuer == 2)
